import React from 'react';
import { FaQuoteLeft } from 'react-icons/fa';
import "./Testimonial.css";
import { Swiper, SwiperSlide } from 'swiper/react';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
import 'swiper/css/effect-coverflow';
import { Autoplay } from 'swiper/modules'; 
// Slick settings for the swiper
const settings = {
  dots: true,
  infinite: true,
  speed: 500,
  autoplay: true,
  autoplaySpeed: 2000,
  slidesToShow: 1,
  slidesToScroll: 1,
  centerMode: false,
  focusOnSelect: true,
  responsive: [
    {
      breakpoint: 700,
      settings: {
        slidesToShow: 1,
        slidesToScroll: 1,
      },
    },
  ],
};



function Testimonial() {
  return (
    <div className="container-fluid py-5 testimonialpart">
      <h1 className="mb-5 subhead2 text-light text-center">What Clients Say</h1>
     <div className='swipercontentarea1'>
      <Swiper
          modules={[Autoplay]}  
          grabCursor={true}
          centeredSlides={true}
          slidesPerView="1"  
          loop={true}
          autoplay={{
            delay: 5000,
            disableOnInteraction: false,
          }}
          className='mySwiper1'
          style={{ overflow: 'hidden' }} 
        >
          <SwiperSlide>
            <div className="testimonial-card">
              <div className="testimonial-content px-5">
              <div className="quote-container py-4">
                <FaQuoteLeft size={30} color="#0D868F" />
              </div>
              <p className="phylotext ">The hard work and support of Oviya MedSafe employees is appreciated and they have been flexible in taking on roles as per the demands of the project, while remaining amiable and enthusiastic throughout.</p>
            </div>
            <div className="client-info">
              <h4 className="testimonialclient">AVP- Medical Affairs</h4>
              <p className="text-dark ">US-Headquartered Innovator Pharma</p>
            </div>
            </div>
          </SwiperSlide>

          <SwiperSlide>
                 
              <div className="testimonial-card" >
              <div className="testimonial-content px-5">
              <div className="quote-container">
                <FaQuoteLeft size={30} color="#0D868F" />
              </div>
              <p className="phylotext">It has indeed been a pleasure working with Oviya MedSafe! Timely execution and great quality work! We are happy that our trust paid off well. We would really recommend Oviya MedSafe for a cost effective and quality work in the field of Pharmacovigilance!</p>
            </div>
              <div className="client-info">
              <h4 className="testimonialclient">Global Safety Lead</h4>
              <p className="text-dark">Indian multinational generic pharma</p>
            </div>
                
              
            </div>
          </SwiperSlide>

          <SwiperSlide>
           
              <div className="testimonial-card" >
              <div className="testimonial-content px-5">
              <div className="quote-container">
                <FaQuoteLeft size={30} color="#0D868F" />
              </div>
              <p className="phylotext">Oviya MedSafe has a deep understanding of global PV regulatory requirements throughout the lifecycle of a product. As a new UK MAH, we are a proud beneficiary of their end-to-end PV Support.</p>
            </div>
            <div className="client-info">
              <h4 className="testimonialclient">Operations Head</h4>
              <p className="text-dark">UK-based Speciality Pharma</p>
            </div>              
              </div>         
          </SwiperSlide>

        </Swiper>
        </div>
    </div>
  );
}

export default Testimonial;
